        }
      }
    },
    openModal() {
      this.showGrid = true
      this.filterText = ''
      this.tempSelected = [...this.internalSelected]
      this.$emit('open')
      this.$nextTick(() => {
        this.$refs.selectorModal?.showModal()
      })
    },
    closeModal() {
      this.showGrid = false
      this.internalSelected = [...this.tempSelected]
      this.$refs.selectorModal?.close()
    },
    confirmModal() {
      this.showGrid = false
      this.emitSelectionChange()
      this.$refs.selectorModal?.close()
    },
    handleModalBackdropClick(event) {
      if (event.target === this.$refs.selectorModal) {
        this.closeModal()
      }
    },
    emitSelectionChange() {
      const updated = (this.items || []).filter(i => this.internalSelected.includes(i.name))
      this.$emit('update:selected-items', updated)
    },
    isItemSelected(itemName) {
      return this.internalSelected.includes(itemName)
    },
    selectItem(item) {
      if (this.isSingleSelect) {
        if (this.allowDeselect && this.internalSelected[0] === item.name) {
          this.internalSelected = []
        } else {
          this.internalSelected = [item.name]
        }
        if (!this.useModal) {
          this.emitSelectionChange()
          this.closeModal()
        }
      } else {
        const idx = this.internalSelected.indexOf(item.name)
        if (idx > -1) {
          this.internalSelected.splice(idx, 1)
        } else {
          this.internalSelected.push(item.name)
        }
        if (!this.useModal) {
          this.emitSelectionChange()
        }
      }
    },
    deselectAll() {
      this.internalSelected = []
      if (!this.useModal) {
        this.emitSelectionChange()
      }
    },
    handleDocumentClick(event) {
      if (this.useModal) return
      if (!this.$el.contains(event.target)) this.showGrid = false
    }
  }
}
</script>
```

| Change | Details |
|--------|---------|
| **confirmModal()** | New method: emits changes and closes modal when "Done" is clicked |
| **closeModal()** | Updated: reverts to `tempSelected` on backdrop/close without emitting |
| **openModal()** | Updated: saves current selection to `tempSelected` before opening |
| **tempSelected** | New data property: stores temporary selection state while modal is open |
| **selectItem()** | Updated: only emits for dropdown mode (when `!useModal`), defers emission for modal mode |
| **deselectAll()** | Updated: only emits for dropdown mode |
| **emitSelectionChange()** | New method: centralized emission logic |

